INSERT INTO `sys_oper_log` VALUES (823, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">您好【{user_name}】，您提交的宠物【{name}】托养申请信息不全故已取消。</strong></p><p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">若后续有托养需求，可随时重新提交申请。</strong></p>\",\"createTime\":\"2025-12-07 17:06:20\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":9,\"templateName\":\"托养申请已取消模板\",\"title\":\"托养申请取消通知\",\"updateTime\":\"2025-12-07 17:08:49\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-07 09:08:50', 116);
INSERT INTO `sys_oper_log` VALUES (824, '通知模板', 1, 'com.ruoyi.pet.controller.NoticeTemplateController.add()', 'POST', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">您好【{user_name}】，您已成功取消宠物【{name}】的托养申请。</strong></p><p><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">若有其他需求，欢迎随时使用我们的服务。</strong></p>\",\"createTime\":\"2025-12-07 17:09:24\",\"params\":{},\"status\":0,\"templateId\":10,\"templateName\":\"用户主动取消托养模板\",\"title\":\"您已主动取消托养申请\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-07 09:09:25', 108);
