INSERT INTO `sys_oper_log` VALUES (1205, '救助登记', 2, 'com.ruoyi.pet.controller.RescueController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/rescue', '127.0.0.1', '内网IP', '{\"createBy\":\"admin\",\"createTime\":\"2025-12-06 18:09:13\",\"handleId\":1,\"handleRemark\":\"已经派人处理\",\"handleTime\":\"2025-12-07 00:00:00\",\"images\":\"2025/12/10/屏幕截图 2025-07-13 141932_20251210214322A001.png\",\"isDeleted\":0,\"location\":\"济南市长清区大学路3501号\",\"params\":{},\"petDesc\":\"好可爱的一个小猫，但是伤势比较重，希望得到救助\",\"reporterName\":\"均均\",\"reporterPhone\":\"15725683781\",\"rescueId\":2,\"status\":2,\"updateBy\":\"admin\",\"updateTime\":\"2025-12-10 21:43:26\",\"userId\":1}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-10 13:43:26', 98);
INSERT INTO `sys_oper_log` VALUES (1206, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">您好【{user_name}】，您提交的【{pet_name}】领养申请已成功进入待处理队列，我们会尽快安排审核，请耐心等待。</strong></p>\",\"createTime\":\"2025-12-08 14:12:35\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":14,\"templateName\":\"领养申请待处理通知模板\",\"title\":\"您的领养申请已进入待处理状态\",\"updateTime\":\"2025-12-10 22:45:18\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-10 14:45:18', 99);
INSERT INTO `sys_oper_log` VALUES (1207, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">您好【{user_name}】，您的领养申请已审核通过！【{pet_name}】已经迫不及待与你见面啦！请及时前往【{address}】店铺办理后续手续。</strong></p>\",\"createTime\":\"2025-12-08 14:13:52\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":15,\"templateName\":\"领养申请通过通知模板\",\"title\":\"您的领养申请已审核通过\",\"updateTime\":\"2025-12-10 22:46:33\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-10 14:46:33', 102);
INSERT INTO `sys_oper_log` VALUES (1208, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><span style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">您好【{user_name}】，很抱歉您的关于宠物</span><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">【{pet_name}】</strong><span style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">的领养申请未通过审核，可补充材料后重新提交申请。</span></p>\",\"createTime\":\"2025-12-08 14:14:51\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":16,\"templateName\":\"领养申请未通过通知模板\",\"title\":\"您的领养申请未通过审核\",\"updateTime\":\"2025-12-10 22:47:33\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-10 14:47:33', 106);
INSERT INTO `sys_oper_log` VALUES (1209, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><span style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">您好【</span><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">{user_name}</strong><span style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">】，很抱歉您的关于宠物</span><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">【{pet_name}】</strong><span style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">的领养申请未通过审核，可补充材料后重新提交申请。</span></p>\",\"createTime\":\"2025-12-08 14:14:51\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":16,\"templateName\":\"领养申请未通过通知模板\",\"title\":\"您的领养申请未通过审核\",\"updateTime\":\"2025-12-10 22:47:54\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-10 14:47:54', 309);
INSERT INTO `sys_oper_log` VALUES (1210, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">您好【{user_name}】，您已成功领养宠物【{pet_name}】。请记得按时带宠物前往【{address}】店铺进行健康检查哦！</strong></p>\",\"createTime\":\"2025-12-08 14:15:28\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":17,\"templateName\":\"领养成功通知模板\",\"title\":\"恭喜您领养到心仪的宠物！\",\"updateTime\":\"2025-12-10 22:48:22\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-10 14:48:22', 103);
INSERT INTO `sys_oper_log` VALUES (1211, '发送通知', 1, 'com.ruoyi.pet.controller.NoticeTemplateController.sendNoticeByNoticeTemplate()', 'POST', 1, 'admin', '研发部门', '/pet/template/sendNotice', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">您好【isen】，您的领养申请已审核通过！【天天】已经迫不及待与你见面啦！请及时前往【未知地点】店铺办理后续手续。</strong></p>\",\"petId\":2,\"templateId\":15,\"title\":\"您的领养申请已审核通过\",\"userId\":1}', '40', 0, NULL, '2025-12-10 14:54:22', 383);
