INSERT INTO `sys_oper_log` VALUES (1232, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">您好【{user_name}】，您提交的宠物【{pet_name}】托养申请已成功接收，目前处于待审核状态。</strong></p><p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">我们会尽快处理您的申请，请耐心等待审核结果.</strong></p>\",\"createTime\":\"2025-12-07 16:45:36\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":5,\"templateName\":\"托养申请待审核模板\",\"title\":\"托养申请待审核通知\",\"updateTime\":\"2025-12-12 18:01:43\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-12 10:01:43', 299);
INSERT INTO `sys_oper_log` VALUES (1233, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">您好【{user_name}】，很抱歉您提交的宠物【{pet_name}】托养申请未通过审核。</strong></p><p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">若有疑问，可联系客服咨询具体原因，感谢您的理解。</strong></p>\",\"createTime\":\"2025-12-07 16:50:09\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":6,\"templateName\":\"托养申请不通过模板\",\"title\":\"托养申请审核结果通知\",\"updateTime\":\"2025-12-12 18:01:51\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-12 10:01:51', 86);
INSERT INTO `sys_oper_log` VALUES (1234, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">您好【{user_name}】，您的宠物【{pet_name}】托养申请已审核通过并确认。</strong></p><p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">请在【{start_date}】携带宠物【{pet_name}】前往【{address}】店铺办理送宠手续，我们已准备好接待。</strong></p>\",\"createTime\":\"2025-12-07 17:01:42\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":7,\"templateName\":\"托养申请已通过待送宠模板\",\"title\":\"托养申请已通过（待送宠）\",\"updateTime\":\"2025-12-12 18:02:12\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-12 10:02:11', 108);
INSERT INTO `sys_oper_log` VALUES (1235, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">您好【{user_name}】，您的宠物【{pet_name}】已顺利入住【{address}】托养店铺，目前处于托养中。</strong></p><p><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">我们会悉心照料它，您可随时联系客服了解宠物近况。﻿</strong></p>\",\"createTime\":\"2025-12-07 17:02:54\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":8,\"templateName\":\"宠物托养中模板\",\"title\":\"您的宠物已进入托养状态\",\"updateTime\":\"2025-12-12 18:02:21\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-12 10:02:20', 321);
INSERT INTO `sys_oper_log` VALUES (1236, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">您好【{user_name}】，您提交的宠物【{pet_name}】托养申请信息不全故已取消。</strong></p><p><strong style=\\\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\\\">若后续有托养需求，可随时重新提交申请。</strong></p>\",\"createTime\":\"2025-12-07 17:06:20\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":9,\"templateName\":\"托养申请已取消模板\",\"title\":\"托养申请取消通知\",\"updateTime\":\"2025-12-12 18:02:28\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-12 10:02:28', 323);
INSERT INTO `sys_oper_log` VALUES (1237, '通知模板', 2, 'com.ruoyi.pet.controller.NoticeTemplateController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/template', '127.0.0.1', '内网IP', '{\"content\":\"<p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">您好【{user_name}】，您已成功取消宠物【{pet_name}】的托养申请。</strong></p><p><strong style=\\\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\\\">若有其他需求，欢迎随时使用我们的服务。</strong></p>\",\"createTime\":\"2025-12-07 17:09:25\",\"isDeleted\":0,\"params\":{},\"status\":0,\"templateId\":10,\"templateName\":\"用户主动取消托养模板\",\"title\":\"您已主动取消托养申请\",\"updateTime\":\"2025-12-12 18:02:38\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-12 10:02:38', 321);
