INSERT INTO `sys_oper_log` VALUES (1250, '宠物信息', 1, 'com.ruoyi.pet.controller.PetController.add()', 'POST', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":11,\"breed\":\"金毛\",\"createTime\":\"2025-12-14 12:46:17\",\"deptId\":1,\"description\":\"胖乎乎的身体包裹着阳光般的姜黄色毛发，琥珀色的眼睛像两颗融化的蜜糖。\",\"dewormingInterval\":3,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/1678.jpg_wh860_20251214124353A002.jpg\",\"immunity\":0,\"insectRepellent\":1,\"name\":\"布丁\",\"neuter\":1,\"params\":{},\"petId\":7,\"species\":1,\"status\":0}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 04:46:24', 105);
INSERT INTO `sys_oper_log` VALUES (1251, '宠物信息', 1, 'com.ruoyi.pet.controller.PetController.add()', 'POST', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":3,\"breed\":\"哈士奇\",\"createTime\":\"2025-12-14 12:47:21\",\"deptId\":3,\"description\":\"拥有冰蓝色眼睛和灰白相间“面具脸”的帅气大狗，外表高傲如北欧神祇，内里却是个不折不扣的“喜剧演员”\",\"dewormingInterval\":9,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/0439.jpg_wh860_20251214124640A003.jpg\",\"immunity\":0,\"insectRepellent\":1,\"name\":\"可乐\",\"neuter\":1,\"params\":{},\"petId\":8,\"species\":1,\"status\":0}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 04:47:28', 98);
INSERT INTO `sys_oper_log` VALUES (1252, '宠物信息', 1, 'com.ruoyi.pet.controller.PetController.add()', 'POST', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":7,\"breed\":\"缅因猫\",\"createTime\":\"2025-12-14 12:49:43\",\"deptId\":3,\"dewormingInterval\":10,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/8136.jpg_wh860_20251214124744A004.jpg\",\"immunity\":0,\"insectRepellent\":1,\"name\":\"奶糖\",\"neuter\":1,\"params\":{},\"petId\":9,\"species\":0,\"status\":0}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 04:49:50', 154);
INSERT INTO `sys_oper_log` VALUES (1253, '宠物信息', 1, 'com.ruoyi.pet.controller.PetController.add()', 'POST', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":10,\"breed\":\"蓝白\",\"createTime\":\"2025-12-14 12:51:21\",\"deptId\":4,\"description\":\"它行走时，脊背上的虎斑纹如流动的山水墨痕。眼神在警觉时是紧绷的铜铃，放松时则眯成两弯蔑视众生的月牙。最爱在深夜进行“跑酷”，追逐根本不存在的猎物，最后以一声满足的“喵”总结战果。当你打开零食袋，无论它在屋子的哪个角落，三秒内必会端坐在你面前，尾巴尖优雅地卷成一个问号。\",\"dewormingInterval\":11,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/R-C_20251214125023A005.jpg\",\"immunity\":0,\"insectRepellent\":1,\"name\":\"奶球\",\"neuter\":1,\"params\":{},\"petId\":10,\"species\":0,\"status\":0}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 04:51:28', 110);
INSERT INTO `sys_oper_log` VALUES (1254, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":7,\"breed\":\"缅因猫\",\"createTime\":\"2025-12-14 12:49:43\",\"deptId\":3,\"description\":\"它像一团移动的、蓬松的晚霞，摊在丝绒垫子上便是最华贵的装饰。碧绿的眼睛里盛着整个森林的幽静，看人时带着与生俱来的贵族的疏离。它允许你抚摸，爪子却轻轻搭在你手上，仿佛在说：“这是朕的恩赐。” 唯一的热情献给了毛线球——那时，它才短暂地变回一只天真烂漫的小猫。\",\"dewormingInterval\":10,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/8136.jpg_wh860_20251214124744A004.jpg\",\"immunity\":0,\"insectRepellent\":1,\"isDeleted\":0,\"name\":\"奶糖\",\"neuter\":1,\"params\":{},\"petId\":9,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 12:51:39\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 04:51:46', 92);
