INSERT INTO `sys_oper_log` VALUES (1262, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":9,\"breed\":\"拉布拉多\",\"createTime\":\"2025-12-14 12:43:34\",\"deptId\":1,\"description\":\"软乎乎没脾气，被揉肚子只会发出呼噜呼噜的低音炮，见人就把肚皮翻过来求贴贴，吃东西慢吞吞，连伸爪子都是轻轻的，自带 “岁月静好” buff。\",\"dewormingInterval\":1,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/90_20251214124245A001.jpg\",\"immunity\":0,\"insectRepellent\":1,\"isDeleted\":0,\"name\":\"豆豆\",\"neuter\":1,\"params\":{},\"petId\":6,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-14 15:17:40\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 07:17:47', 196);
INSERT INTO `sys_oper_log` VALUES (1263, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":1,\"breed\":\"哈机密\",\"createTime\":\"2025-12-04 21:20:25\",\"deptId\":1,\"description\":\"典型 “猫主子”，从不主动黏人，你喊它顶多甩甩尾巴，摸它超过 3 秒就甩头走开，但会偷偷蹲在高处盯着你，睡前却会悄咪咪蜷在你枕头边（仅限它心情好）。\",\"dewormingInterval\":1,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/12/屏幕截图 2025-06-26 211958_20251212161131A007.png\",\"immunity\":0,\"insectRepellent\":1,\"isDeleted\":0,\"location\":\"11\",\"name\":\"哈哈哈\",\"neuter\":1,\"params\":{},\"petId\":4,\"species\":0,\"status\":5,\"updateTime\":\"2025-12-14 15:17:58\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 07:18:05', 156);
INSERT INTO `sys_oper_log` VALUES (1264, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":6,\"breed\":\"暹罗\",\"createTime\":\"2025-12-04 18:40:52\",\"deptId\":1,\"description\":\"“人形挂件” 本件，你走到哪跟到哪，蹲厕所都要扒门缝，翻书时会把爪子搭在你手上，求抱抱时发出细细的 “喵呜” 声，被放下就委屈巴巴蹭腿。\",\"dewormingInterval\":35,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/12/屏幕截图(14)_20251212160913A004.png\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-03 00:00:00\",\"isDeleted\":0,\"location\":\"济南市\",\"name\":\"天天\",\"neuter\":1,\"params\":{},\"petId\":2,\"remark\":\"天天太可爱了\",\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 15:18:11\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 07:18:19', 195);
INSERT INTO `sys_oper_log` VALUES (1265, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":12,\"breed\":\"橘猫\",\"createTime\":\"2025-12-14 12:54:30\",\"deptId\":4,\"description\":\"精力旺盛的 “闯祸精”，凌晨五点准时跑酷，推掉桌上的笔、扒拉垃圾桶是日常，玩逗猫棒能跳半米高，累了就瘫在你怀里打呼噜，主打一个 “疯玩后秒乖”。\",\"dewormingInterval\":9,\"gender\":1,\"healthInfo\":\"肥胖\",\"images\":\"2025/12/14/OIP-C_20251214125307A006.jpg\",\"immunity\":0,\"insectRepellent\":1,\"isDeleted\":0,\"name\":\"加菲猫\",\"neuter\":1,\"params\":{},\"petId\":11,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 15:19:38\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 07:19:46', 105);
INSERT INTO `sys_oper_log` VALUES (1266, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":9,\"breed\":\"拉布拉多\",\"createTime\":\"2025-12-14 12:43:34\",\"deptId\":1,\"description\":\"软乎乎没脾气，被揉肚子只会发出呼噜呼噜的低音炮，见人就把肚皮翻过来求贴贴，吃东西慢吞吞，连伸爪子都是轻轻的，自带 “岁月静好” buff。\",\"dewormingInterval\":1,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/90_20251214124245A001.jpg\",\"immunity\":1,\"insectRepellent\":0,\"isDeleted\":0,\"name\":\"豆豆\",\"neuter\":1,\"params\":{},\"petId\":6,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-14 15:22:17\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 07:22:24', 131);
INSERT INTO `sys_oper_log` VALUES (1267, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":1,\"breed\":\"哈机密\",\"createTime\":\"2025-12-04 21:20:25\",\"deptId\":1,\"description\":\"典型 “猫主子”，从不主动黏人，你喊它顶多甩甩尾巴，摸它超过 3 秒就甩头走开，但会偷偷蹲在高处盯着你，睡前却会悄咪咪蜷在你枕头边（仅限它心情好）。\",\"dewormingInterval\":1,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/12/屏幕截图 2025-06-26 211958_20251212161131A007.png\",\"immunity\":0,\"insectRepellent\":0,\"isDeleted\":0,\"location\":\"11\",\"name\":\"哈哈哈\",\"neuter\":1,\"params\":{},\"petId\":4,\"species\":0,\"status\":5,\"updateTime\":\"2025-12-14 15:22:26\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 07:22:33', 109);
INSERT INTO `sys_oper_log` VALUES (1268, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":10,\"breed\":\"蓝白\",\"createTime\":\"2025-12-14 12:51:21\",\"deptId\":4,\"description\":\"它行走时，脊背上的虎斑纹如流动的山水墨痕。眼神在警觉时是紧绷的铜铃，放松时则眯成两弯蔑视众生的月牙。最爱在深夜进行“跑酷”，追逐根本不存在的猎物，最后以一声满足的“喵”总结战果。当你打开零食袋，无论它在屋子的哪个角落，三秒内必会端坐在你面前，尾巴尖优雅地卷成一个问号。\",\"dewormingInterval\":11,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/R-C_20251214125023A005.jpg\",\"immunity\":0,\"insectRepellent\":1,\"isDeleted\":0,\"name\":\"奶球\",\"neuter\":0,\"params\":{},\"petId\":10,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 15:22:32\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 07:22:40', 106);
