INSERT INTO `sys_oper_log` VALUES (1298, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":14,\"breed\":\"英短\",\"createTime\":\"2025-12-04 19:00:55\",\"deptId\":3,\"description\":\"小木好乖\",\"dewormingInterval\":2,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/12/1749303055973_20251212161013A005.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-01\",\"isDeleted\":0,\"name\":\"小木\",\"neuter\":1,\"params\":{},\"petId\":3,\"remark\":\"无\",\"species\":0,\"status\":1,\"updateTime\":\"2025-12-14 18:49:30\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:49:38', 61);
INSERT INTO `sys_oper_log` VALUES (1299, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":6,\"breed\":\"暹罗\",\"createTime\":\"2025-12-04 18:40:52\",\"deptId\":1,\"description\":\"“人形挂件” 本件，你走到哪跟到哪，蹲厕所都要扒门缝，翻书时会把爪子搭在你手上，求抱抱时发出细细的 “喵呜” 声，被放下就委屈巴巴蹭腿。\",\"dewormingInterval\":35,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/12/屏幕截图(14)_20251212160913A004.png\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-03\",\"isDeleted\":0,\"location\":\"济南市\",\"name\":\"天天\",\"neuter\":1,\"params\":{},\"petId\":2,\"remark\":\"天天太可爱了\",\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 18:49:36\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:49:44', 45);
INSERT INTO `sys_oper_log` VALUES (1300, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":1,\"breed\":\"哈机密\",\"createTime\":\"2025-12-04 21:20:25\",\"deptId\":1,\"description\":\"典型 “猫主子”，从不主动黏人，你喊它顶多甩甩尾巴，摸它超过 3 秒就甩头走开，但会偷偷蹲在高处盯着你，睡前却会悄咪咪蜷在你枕头边（仅限它心情好）。\",\"dewormingInterval\":6,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/12/屏幕截图 2025-06-26 211958_20251212161131A007.png\",\"immunity\":0,\"insectRepellent\":0,\"insectRepellentLastTime\":\"2025-12-01\",\"isDeleted\":0,\"location\":\"11\",\"name\":\"哈哈哈\",\"neuter\":1,\"params\":{},\"petId\":4,\"species\":0,\"status\":5,\"updateTime\":\"2025-12-14 18:49:45\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:49:53', 43);
INSERT INTO `sys_oper_log` VALUES (1301, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":9,\"breed\":\"拉布拉多\",\"createTime\":\"2025-12-14 12:43:34\",\"deptId\":1,\"description\":\"软乎乎没脾气，被揉肚子只会发出呼噜呼噜的低音炮，见人就把肚皮翻过来求贴贴，吃东西慢吞吞，连伸爪子都是轻轻的，自带 “岁月静好” buff。\",\"dewormingInterval\":7,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/90_20251214124245A001.jpg\",\"immunity\":1,\"insectRepellent\":0,\"insectRepellentLastTime\":\"2025-12-09\",\"isDeleted\":0,\"name\":\"豆豆\",\"neuter\":1,\"params\":{},\"petId\":6,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-14 18:49:56\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:03', 41);
INSERT INTO `sys_oper_log` VALUES (1302, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":11,\"breed\":\"金毛\",\"createTime\":\"2025-12-14 12:46:17\",\"deptId\":1,\"description\":\"胖乎乎的身体包裹着阳光般的姜黄色毛发，琥珀色的眼睛像两颗融化的蜜糖。\",\"dewormingInterval\":3,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/1678.jpg_wh860_20251214124353A002.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-03\",\"isDeleted\":0,\"name\":\"布丁\",\"neuter\":1,\"params\":{},\"petId\":7,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-14 18:50:02\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:09', 53);
INSERT INTO `sys_oper_log` VALUES (1303, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":3,\"breed\":\"哈士奇\",\"createTime\":\"2025-12-14 12:47:21\",\"deptId\":3,\"description\":\"拥有冰蓝色眼睛和灰白相间“面具脸”的帅气大狗，外表高傲如北欧神祇，内里却是个不折不扣的“喜剧演员”\",\"dewormingInterval\":9,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/0439.jpg_wh860_20251214124640A003.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isDeleted\":0,\"name\":\"可乐\",\"neuter\":1,\"params\":{},\"petId\":8,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-14 18:50:09\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:16', 41);
INSERT INTO `sys_oper_log` VALUES (1304, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":3,\"breed\":\"哈士奇\",\"createTime\":\"2025-12-14 12:47:21\",\"deptId\":3,\"description\":\"拥有冰蓝色眼睛和灰白相间“面具脸”的帅气大狗，外表高傲如北欧神祇，内里却是个不折不扣的“喜剧演员”\",\"dewormingInterval\":9,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/0439.jpg_wh860_20251214124640A003.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isDeleted\":0,\"name\":\"可乐\",\"neuter\":1,\"params\":{},\"petId\":8,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-14 18:50:15\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:23', 44);
INSERT INTO `sys_oper_log` VALUES (1305, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":7,\"breed\":\"缅因猫\",\"createTime\":\"2025-12-14 12:49:43\",\"deptId\":3,\"description\":\"它像一团移动的、蓬松的晚霞，摊在丝绒垫子上便是最华贵的装饰。碧绿的眼睛里盛着整个森林的幽静，看人时带着与生俱来的贵族的疏离。它允许你抚摸，爪子却轻轻搭在你手上，仿佛在说：“这是朕的恩赐。” 唯一的热情献给了毛线球——那时，它才短暂地变回一只天真烂漫的小猫。\",\"dewormingInterval\":10,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/8136.jpg_wh860_20251214124744A004.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isDeleted\":0,\"name\":\"奶糖\",\"neuter\":1,\"params\":{},\"petId\":9,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 18:50:20\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:28', 56);
INSERT INTO `sys_oper_log` VALUES (1306, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":7,\"breed\":\"缅因猫\",\"createTime\":\"2025-12-14 12:49:43\",\"deptId\":3,\"description\":\"它像一团移动的、蓬松的晚霞，摊在丝绒垫子上便是最华贵的装饰。碧绿的眼睛里盛着整个森林的幽静，看人时带着与生俱来的贵族的疏离。它允许你抚摸，爪子却轻轻搭在你手上，仿佛在说：“这是朕的恩赐。” 唯一的热情献给了毛线球——那时，它才短暂地变回一只天真烂漫的小猫。\",\"dewormingInterval\":10,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/8136.jpg_wh860_20251214124744A004.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isDeleted\":0,\"name\":\"奶糖\",\"neuter\":1,\"params\":{},\"petId\":9,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 18:50:25\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:33', 40);
INSERT INTO `sys_oper_log` VALUES (1307, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":7,\"breed\":\"缅因猫\",\"createTime\":\"2025-12-14 12:49:43\",\"deptId\":3,\"description\":\"它像一团移动的、蓬松的晚霞，摊在丝绒垫子上便是最华贵的装饰。碧绿的眼睛里盛着整个森林的幽静，看人时带着与生俱来的贵族的疏离。它允许你抚摸，爪子却轻轻搭在你手上，仿佛在说：“这是朕的恩赐。” 唯一的热情献给了毛线球——那时，它才短暂地变回一只天真烂漫的小猫。\",\"dewormingInterval\":10,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/8136.jpg_wh860_20251214124744A004.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isDeleted\":0,\"name\":\"奶糖\",\"neuter\":1,\"params\":{},\"petId\":9,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 18:50:29\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:36', 56);
INSERT INTO `sys_oper_log` VALUES (1308, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":10,\"breed\":\"蓝白\",\"createTime\":\"2025-12-14 12:51:21\",\"deptId\":4,\"description\":\"它行走时，脊背上的虎斑纹如流动的山水墨痕。眼神在警觉时是紧绷的铜铃，放松时则眯成两弯蔑视众生的月牙。最爱在深夜进行“跑酷”，追逐根本不存在的猎物，最后以一声满足的“喵”总结战果。当你打开零食袋，无论它在屋子的哪个角落，三秒内必会端坐在你面前，尾巴尖优雅地卷成一个问号。\",\"dewormingInterval\":11,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/R-C_20251214125023A005.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isDeleted\":0,\"name\":\"奶球\",\"neuter\":0,\"params\":{},\"petId\":10,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 18:50:34\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:41', 45);
INSERT INTO `sys_oper_log` VALUES (1309, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":12,\"breed\":\"橘猫\",\"createTime\":\"2025-12-14 12:54:30\",\"deptId\":4,\"description\":\"精力旺盛的 “闯祸精”，凌晨五点准时跑酷，推掉桌上的笔、扒拉垃圾桶是日常，玩逗猫棒能跳半米高，累了就瘫在你怀里打呼噜，主打一个 “疯玩后秒乖”。\",\"dewormingInterval\":9,\"gender\":1,\"healthInfo\":\"肥胖\",\"images\":\"2025/12/14/OIP-C_20251214125307A006.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isDeleted\":0,\"name\":\"加菲猫\",\"neuter\":0,\"params\":{},\"petId\":11,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-14 18:50:40\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-14 10:50:47', 39);
