INSERT INTO `sys_oper_log` VALUES (1506, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":10,\"breed\":\"蓝白\",\"createTime\":\"2025-12-14 12:51:21\",\"deptId\":4,\"description\":\"它行走时，脊背上的虎斑纹如流动的山水墨痕。眼神在警觉时是紧绷的铜铃，放松时则眯成两弯蔑视众生的月牙。最爱在深夜进行“跑酷”，追逐根本不存在的猎物，最后以一声满足的“喵”总结战果。当你打开零食袋，无论它在屋子的哪个角落，三秒内必会端坐在你面前，尾巴尖优雅地卷成一个问号。\",\"dewormingInterval\":11,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/R-C_20251214125023A005.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isCollect\":0,\"isDeleted\":0,\"location\":\"小船宠物店长清大学城\",\"name\":\"奶球\",\"neuter\":0,\"params\":{},\"petId\":10,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-17 12:18:35\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-17 04:18:33', 39);
INSERT INTO `sys_oper_log` VALUES (1507, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":7,\"breed\":\"缅因猫\",\"createTime\":\"2025-12-14 12:49:43\",\"deptId\":3,\"description\":\"它像一团移动的、蓬松的晚霞，摊在丝绒垫子上便是最华贵的装饰。碧绿的眼睛里盛着整个森林的幽静，看人时带着与生俱来的贵族的疏离。它允许你抚摸，爪子却轻轻搭在你手上，仿佛在说：“这是朕的恩赐。” 唯一的热情献给了毛线球——那时，它才短暂地变回一只天真烂漫的小猫。\",\"dewormingInterval\":10,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/8136.jpg_wh860_20251214124744A004.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isCollect\":0,\"isDeleted\":0,\"location\":\"人民宠物店\",\"name\":\"奶糖\",\"neuter\":1,\"params\":{},\"petId\":9,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-17 12:19:26\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-17 04:19:24', 35);
INSERT INTO `sys_oper_log` VALUES (1508, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":12,\"breed\":\"橘猫\",\"createTime\":\"2025-12-14 12:54:30\",\"deptId\":4,\"description\":\"精力旺盛的 “闯祸精”，凌晨五点准时跑酷，推掉桌上的笔、扒拉垃圾桶是日常，玩逗猫棒能跳半米高，累了就瘫在你怀里打呼噜，主打一个 “疯玩后秒乖”。\",\"dewormingInterval\":9,\"gender\":1,\"healthInfo\":\"肥胖\",\"images\":\"2025/12/14/OIP-C_20251214125307A006.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isCollect\":0,\"isDeleted\":0,\"location\":\"小船宠物店\",\"name\":\"加菲猫\",\"neuter\":0,\"params\":{},\"petId\":11,\"species\":0,\"status\":0,\"updateTime\":\"2025-12-17 12:19:38\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-17 04:19:36', 34);
INSERT INTO `sys_oper_log` VALUES (1509, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":3,\"breed\":\"哈士奇\",\"createTime\":\"2025-12-14 12:47:21\",\"deptId\":3,\"description\":\"拥有冰蓝色眼睛和灰白相间“面具脸”的帅气大狗，外表高傲如北欧神祇，内里却是个不折不扣的“喜剧演员”\",\"dewormingInterval\":9,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/0439.jpg_wh860_20251214124640A003.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-02\",\"isCollect\":0,\"isDeleted\":0,\"location\":\"人民宠物店\",\"name\":\"可乐\",\"neuter\":1,\"params\":{},\"petId\":8,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-17 12:19:51\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-17 04:19:49', 40);
INSERT INTO `sys_oper_log` VALUES (1510, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":9,\"breed\":\"拉布拉多\",\"createTime\":\"2025-12-14 12:43:34\",\"deptId\":1,\"description\":\"软乎乎没脾气，被揉肚子只会发出呼噜呼噜的低音炮，见人就把肚皮翻过来求贴贴，吃东西慢吞吞，连伸爪子都是轻轻的，自带 “岁月静好” buff。\",\"dewormingInterval\":7,\"gender\":1,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/90_20251214124245A001.jpg\",\"immunity\":1,\"insectRepellent\":0,\"insectRepellentLastTime\":\"2025-12-09\",\"isCollect\":0,\"isDeleted\":0,\"location\":\"你好宠物店\",\"name\":\"豆豆\",\"neuter\":1,\"params\":{},\"petId\":6,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-17 12:20:00\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-17 04:19:59', 34);
INSERT INTO `sys_oper_log` VALUES (1511, '宠物信息', 2, 'com.ruoyi.pet.controller.PetController.edit()', 'PUT', 1, 'admin', '研发部门', '/pet/pet', '127.0.0.1', '内网IP', '{\"age\":11,\"breed\":\"金毛\",\"createTime\":\"2025-12-14 12:46:17\",\"deptId\":1,\"description\":\"胖乎乎的身体包裹着阳光般的姜黄色毛发，琥珀色的眼睛像两颗融化的蜜糖。\",\"dewormingInterval\":3,\"gender\":0,\"healthInfo\":\"健康\",\"images\":\"2025/12/14/1678.jpg_wh860_20251214124353A002.jpg\",\"immunity\":0,\"insectRepellent\":1,\"insectRepellentLastTime\":\"2025-12-03\",\"isCollect\":0,\"isDeleted\":0,\"location\":\"你好宠物店\",\"name\":\"布丁\",\"neuter\":1,\"params\":{},\"petId\":7,\"species\":1,\"status\":0,\"updateTime\":\"2025-12-17 12:20:17\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-12-17 04:20:16', 36);
