INSERT INTO `tb_notice_template` VALUES (14, '领养申请待处理通知模板', '您的领养申请已进入待处理状态', '<p><strong style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">您好【{user_name}】，您提交的【{pet_name}】领养申请已成功进入待处理队列，我们会尽快安排审核，请耐心等待。</strong></p>', 0, '2025-12-08 14:12:35', NULL, '2025-12-10 22:45:19', NULL, NULL, 0);
INSERT INTO `tb_notice_template` VALUES (15, '领养申请通过通知模板', '您的领养申请已审核通过', '<p><strong style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">您好【{user_name}】，您的领养申请已审核通过！【{pet_name}】已经迫不及待与你见面啦！请及时前往【{address}】店铺办理后续手续。</strong></p>', 0, '2025-12-08 14:13:52', NULL, '2025-12-10 22:46:34', NULL, NULL, 0);
INSERT INTO `tb_notice_template` VALUES (16, '领养申请未通过通知模板', '您的领养申请未通过审核', '<p><span style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">您好【</span><strong style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">{user_name}</strong><span style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">】，很抱歉您的关于宠物</span><strong style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">【{pet_name}】</strong><span style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">的领养申请未通过审核，可补充材料后重新提交申请。</span></p>', 0, '2025-12-08 14:14:51', NULL, '2025-12-10 22:47:54', NULL, NULL, 0);
INSERT INTO `tb_notice_template` VALUES (17, '领养成功通知模板', '恭喜您领养到心仪的宠物！', '<p><strong style=\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\">您好【{user_name}】，您已成功领养宠物【{pet_name}】。请记得按时带宠物前往【{address}】店铺进行健康检查哦！</strong></p>', 0, '2025-12-08 14:15:28', NULL, '2025-12-10 22:48:23', NULL, NULL, 0);
INSERT INTO `tb_notice_template` VALUES (18, '救助申请已处理模板', '救助申请已处理', '<p><strong style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">您好【{user_name}】，您提交的宠物救助申请已完成处理。感谢您的配合。</strong></p>', 0, '2025-12-08 22:40:11', NULL, '2025-12-19 14:10:09', NULL, NULL, 0);
INSERT INTO `tb_notice_template` VALUES (19, '寻宠启事已发布模板', '寻宠启事已发布', '<p><strong style=\"color: rgba(0, 0, 0, 0.85); background-color: rgb(255, 255, 255);\">【寻宠启事已发布】亲爱的【{owner_name}】，您于【{lost_time}】在【{lost_location}】附近走失的宠物（姓名：【{pet_name}】）的寻宠启事已成功发布并推送至附近用户。我们正在全力协助您寻找，请您也保持电话畅通。希望就在眼前，请不要放弃！</strong></p>', 0, '2025-12-19 13:39:34', NULL, '2025-12-19 14:17:49', NULL, NULL, 0);
INSERT INTO `tb_notice_template` VALUES (20, '​寻宠宠物已找到模板', '​宠物已找到通知', '<p><strong style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">【好消息！宠物已找到】亲爱的【{owner_name}】，我们怀着无比喜悦的心情通知您，您走失的宠物【{pet_name}】已经安全找到了！感谢您的信任与耐心等待，这真是太好了！</strong></p>', 0, '2025-12-19 13:40:32', NULL, '2025-12-19 14:18:58', NULL, NULL, 0);
INSERT INTO `tb_notice_template` VALUES (21, '寻宠信息不合规模板', '寻宠信息待完善通知', '<p><strong style=\"background-color: rgb(255, 255, 255); color: rgba(0, 0, 0, 0.85);\">【信息待完善】尊敬的【{owner_name}】，您提交的寻宠信息因 “【{不合规的具体原因，如：联系方式缺失/图片不清晰/地址信息不完整}】”​ 未能通过审核。</strong></p>', 0, '2025-12-19 13:41:34', NULL, '2025-12-19 14:21:24', NULL, NULL, 0);
