INSERT INTO `tb_pet` VALUES (2, '天天', 0, '暹罗', 0, 6, '健康', 1, 0, 1, 35, '2025-12-03 00:00:00', '“人形挂件” 本件，你走到哪跟到哪，蹲厕所都要扒门缝，翻书时会把爪子搭在你手上，求抱抱时发出细细的 “喵呜” 声，被放下就委屈巴巴蹭腿。', 0, '济南市', '2026/03/30/v2-dff8fea2a80de86d9b8b3938cf05be0d_r_20260330223051A008.jpg', 1, '2025-12-04 18:40:52', NULL, '2026-03-30 22:30:54', NULL, '天天太可爱了', 0);
INSERT INTO `tb_pet` VALUES (3, '小木', 0, '英短', 1, 14, '健康', 1, 0, 1, 2, '2025-12-01 00:00:00', '小木好乖', 1, NULL, '2026/03/30/R-C_20260330222958A007.jpg', 3, '2025-12-04 19:00:55', NULL, '2026-03-30 22:30:01', NULL, '无', 0);
INSERT INTO `tb_pet` VALUES (4, '哈哈哈', 0, '哈机密', 0, 1, '健康', 1, 0, 0, 6, '2025-12-01 00:00:00', '典型 “猫主子”，从不主动黏人，你喊它顶多甩甩尾巴，摸它超过 3 秒就甩头走开，但会偷偷蹲在高处盯着你，睡前却会悄咪咪蜷在你枕头边（仅限它心情好）。', 5, '11', '2026/03/30/90_20260330195559A006.jpg', 1, '2025-12-04 21:20:25', NULL, '2026-03-30 19:56:02', NULL, NULL, 0);
INSERT INTO `tb_pet` VALUES (6, '豆豆', 1, '拉布拉多', 1, 9, '健康', 1, 1, 0, 7, '2025-12-09 00:00:00', '软乎乎没脾气，被揉肚子只会发出呼噜呼噜的低音炮，见人就把肚皮翻过来求贴贴，吃东西慢吞吞，连伸爪子都是轻轻的，自带 “岁月静好” buff。', 0, '你好宠物店', '2026/03/30/OIP-C 1_20260330195518A005.jpg', 1, '2025-12-14 12:43:34', NULL, '2026-03-30 19:55:22', NULL, NULL, 0);
INSERT INTO `tb_pet` VALUES (7, '布丁', 1, '金毛', 0, 11, '健康', 1, 0, 1, 3, '2025-12-03 00:00:00', '胖乎乎的身体包裹着阳光般的姜黄色毛发，琥珀色的眼睛像两颗融化的蜜糖。', 0, '你好宠物店', '2026/03/30/OIP-C_20260330195017A004.jpg', 1, '2025-12-14 12:46:17', NULL, '2026-03-30 19:50:20', NULL, NULL, 0);
INSERT INTO `tb_pet` VALUES (8, '可乐', 1, '哈士奇', 1, 3, '健康', 1, 0, 1, 9, '2025-12-02 00:00:00', '拥有冰蓝色眼睛和灰白相间“面具脸”的帅气大狗，外表高傲如北欧神祇，内里却是个不折不扣的“喜剧演员”', 0, '人民宠物店', '2026/03/30/photo-1503256207526-0d5d80fa2f47_20260330194953A003.jpg', 3, '2025-12-14 12:47:21', NULL, '2026-03-30 19:49:57', NULL, NULL, 0);
INSERT INTO `tb_pet` VALUES (9, '奶糖', 0, '缅因猫', 0, 7, '健康', 1, 0, 1, 10, '2025-12-02 00:00:00', '它像一团移动的、蓬松的晚霞，摊在丝绒垫子上便是最华贵的装饰。碧绿的眼睛里盛着整个森林的幽静，看人时带着与生俱来的贵族的疏离。它允许你抚摸，爪子却轻轻搭在你手上，仿佛在说：“这是朕的恩赐。” 唯一的热情献给了毛线球——那时，它才短暂地变回一只天真烂漫的小猫。', 0, '人民宠物店', '2026/03/30/xl_20260330190131A002.jpg', 3, '2025-12-14 12:49:43', NULL, '2026-03-30 19:01:34', NULL, NULL, 0);
INSERT INTO `tb_pet` VALUES (10, '奶球', 0, '蓝白', 0, 10, '健康', 0, 0, 1, 11, '2025-12-02 00:00:00', '它行走时，脊背上的虎斑纹如流动的山水墨痕。眼神在警觉时是紧绷的铜铃，放松时则眯成两弯蔑视众生的月牙。最爱在深夜进行“跑酷”，追逐根本不存在的猎物，最后以一声满足的“喵”总结战果。当你打开零食袋，无论它在屋子的哪个角落，三秒内必会端坐在你面前，尾巴尖优雅地卷成一个问号。', 0, '小船宠物店长清大学城', '2026/03/30/cat-8198720_1920_20260330190109A001.jpg', 4, '2025-12-14 12:51:21', NULL, '2026-03-30 19:01:11', NULL, NULL, 0);
INSERT INTO `tb_pet` VALUES (11, '加菲猫', 0, '橘猫', 1, 12, '肥胖', 0, 0, 1, 9, '2025-12-02 00:00:00', '精力旺盛的 “闯祸精”，凌晨五点准时跑酷，推掉桌上的笔、扒拉垃圾桶是日常，玩逗猫棒能跳半米高，累了就瘫在你怀里打呼噜，主打一个 “疯玩后秒乖”。', 0, '小船宠物店', '2026/03/30/p6yH8VmGqxo_20260330190009A006.jpg', 4, '2025-12-14 12:54:30', NULL, '2026-03-30 19:00:12', NULL, NULL, 0);
INSERT INTO `tb_pet` VALUES (12, '小图', 2, '金丝熊', 0, 10, '健康', 1, 0, 1, 30, '2025-12-20 00:00:00', '体型比较圆润，比较肥美', 0, '', '2026/03/30/photo-1425082661705-1834bfd09dca_20260330183147A005.jpg', 1, '2025-12-20 22:35:42', NULL, '2026-03-30 18:31:49', NULL, '无', 0);
INSERT INTO `tb_pet` VALUES (13, '小浣', 2, '浣熊', 1, 12, '健康', 1, 0, 1, 25, '2025-12-16 00:00:00', '小浣还是每时每刻都非常可爱', 0, NULL, '2026/03/30/photo-1497752531616-c3afd9760a11_20260330183119A004.jpg', 3, '2025-12-20 22:37:46', NULL, '2026-03-30 18:31:22', NULL, '无', 0);
