-- Table structure for tb_lost_pet
-- ----------------------------
DROP TABLE IF EXISTS `tb_lost_pet`;
CREATE TABLE `tb_lost_pet`  (
  `lost_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 寻宠id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `owner_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '主人姓名',
  `owner_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '丢失主人电话',
  `pet_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物姓名',
  `species` tinyint NULL DEFAULT NULL COMMENT '物种(0-猫,1-狗,2-其他)',
  `breed` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '品种',
  `features` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '显著特征',
  `message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '想说的话',
  `lost_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '丢失地点',
  `lost_time` datetime NULL DEFAULT NULL COMMENT '丢失时间',
  `reward` int NULL DEFAULT NULL COMMENT '酬谢金额',
  `images` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物图片',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态(0-寻找，1-已找到)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `create_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除（0-未删除,1-已删除）',
  PRIMARY KEY (`lost_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '宠物丢失表' ROW_FORMAT = DYNAMIC;

