  `title` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通知标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '通知内容模板',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态（0-启用，1-禁用）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
