-- Records of tb_order
-- ----------------------------

-- ----------------------------
-- Table structure for tb_order_item
-- ----------------------------
DROP TABLE IF EXISTS `tb_order_item`;
CREATE TABLE `tb_order_item`  (
  `item_id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单项id',
  `order_id` bigint NULL DEFAULT NULL COMMENT '订单id',
  `resource_id` bigint NULL DEFAULT NULL COMMENT '商品id',
  `resource_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品名称',
  `price` int NULL DEFAULT NULL COMMENT '购买时单价',
  `quantity` int NULL DEFAULT NULL COMMENT '购买数量',
  `total_price` int NULL DEFAULT NULL COMMENT '小计金额',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除（0-未删除，1-已删除）',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '订单详情表（订单项表）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_order_item
-- ----------------------------

-- ----------------------------
-- Table structure for tb_pet
-- ----------------------------
DROP TABLE IF EXISTS `tb_pet`;
CREATE TABLE `tb_pet`  (
  `pet_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 宠物id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物名称',
  `species` tinyint NULL DEFAULT NULL COMMENT '物种（0-猫，1-狗，2-其他）',
  `breed` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '品种(如：金毛)',
  `gender` tinyint NULL DEFAULT 2 COMMENT '性别（0-母，1-公，2-未知）默认是2',
  `age` tinyint NULL DEFAULT NULL COMMENT '年龄',
  `health_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '健康状态描述',
  `neuter` tinyint NULL DEFAULT 2 COMMENT '是否绝育（0-未绝育 1-已绝育 2- 未知）默认是2',
  `immunity` tinyint NULL DEFAULT 2 COMMENT '是否免疫( 0 -已免疫 , 1-未免疫 , 2 - 未知) 默认是2',
  `insect_repellent` tinyint NULL DEFAULT 2 COMMENT '是否驱虫 (0 - 未驱虫  1- 已驱虫 2- 未知) 默认是2',
  `deworming_interval` int NULL DEFAULT NULL COMMENT '驱虫周期（全部以日的形式展示）',
  `insect_repellent_last_time` datetime NULL DEFAULT NULL COMMENT '上回驱虫日期 ',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物描述',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态( 0-待领养,证明在店中\r\n          1 - 托养中\r\n 2 - 已走失\r\n3 - 已领养,被用户领养，不在店中\r\n4 - 救助中\r\n5 - 已救助\r\n6 - 在店中\r\n )',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发现、所在地',
  `images` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物图片',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '所属店铺/站点',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除字段（0-未删除 1-已删除）',
  PRIMARY KEY (`pet_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '宠物信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_pet
-- ----------------------------

-- ----------------------------
-- Table structure for tb_pet_boarding
-- ----------------------------
DROP TABLE IF EXISTS `tb_pet_boarding`;
CREATE TABLE `tb_pet_boarding`  (
  `boarding_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NULL DEFAULT 1 COMMENT '用户id',
  `shop_id` bigint NULL DEFAULT NULL COMMENT '店铺id',
  `shop_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '店铺名称',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物名称',
  `species` tinyint NULL DEFAULT NULL COMMENT '物种',
  `breed` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '品种',
  `gender` tinyint NULL DEFAULT NULL COMMENT '性别',
  `age` tinyint NULL DEFAULT NULL COMMENT '年龄',
  `health_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '健康状态',
  `neuter` tinyint NULL DEFAULT NULL COMMENT '是否绝育',
  `immunity` tinyint NULL DEFAULT NULL COMMENT '是否免疫',
  `insect_repellent` tinyint NULL DEFAULT NULL COMMENT '是否驱虫',
  `deworming_interval` int NULL DEFAULT NULL COMMENT '驱虫周期，天',
  `insect_repellent_last_time` datetime NULL DEFAULT NULL COMMENT '上回驱虫日期',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物描述',
  `start_date` datetime NULL DEFAULT NULL COMMENT '预计开始托养时间',
  `end_date` datetime NULL DEFAULT NULL COMMENT '预计结束时间',
  `total_days` int NULL DEFAULT NULL COMMENT '总托养天数',
  `total_amount` int NULL DEFAULT NULL COMMENT '总费用',
  `special_requirement` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '无' COMMENT '特殊要求',
  `emergency_contact` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '紧急联系人',
  `emergency_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '紧急联系人电话',
  `status` tinyint NULL DEFAULT NULL COMMENT '托养状态（0-待审核，1-已确认，待送宠，2-托养中，3-已完成，4-已取消，5-用户已取消）',
  `reviewer_id` bigint NULL DEFAULT NULL COMMENT '审核人id',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `review_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核备注',
  `check_in_time` datetime NULL DEFAULT NULL COMMENT '实际送宠时间',
  `check_out_time` datetime NULL DEFAULT NULL COMMENT '实际接宠时间',
  `payment_status` tinyint NULL DEFAULT 0 COMMENT '支付状态（0-未支付，1-已支付）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '申请创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '信息更新时间',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除（0-未删除，1-已删除）',
  `images` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物图片',
  PRIMARY KEY (`boarding_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '宠物托养' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_pet_boarding
-- ----------------------------

-- ----------------------------
-- Table structure for tb_pet_resource
-- ----------------------------
DROP TABLE IF EXISTS `tb_pet_resource`;
CREATE TABLE `tb_pet_resource`  (
  `resource_id` bigint NOT NULL AUTO_INCREMENT COMMENT '商品id',
  `resource_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品名称',
  `images` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图片URL',
  `category_id` bigint NULL DEFAULT NULL COMMENT '分类id',
  `category_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类名称',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态（0-上架,1-下架）',
  `specification` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '规格（2kg每包）',
  `stock` bigint NULL DEFAULT 0 COMMENT '默认是0 ,库存数量',
  `sales` bigint NULL DEFAULT 0 COMMENT '销量',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除（0-未删除，1-已删除）',
  `price` int NULL DEFAULT 0 COMMENT '商品价格（单位为分，减少进制误差）',
  `shop_id` bigint NULL DEFAULT NULL COMMENT '店铺id',
  PRIMARY KEY (`resource_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_pet_resource
-- ----------------------------

-- ----------------------------
-- Table structure for tb_rescue
-- ----------------------------
DROP TABLE IF EXISTS `tb_rescue`;
CREATE TABLE `tb_rescue`  (
  `rescue_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键  救助id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '登记用户id',
  `reporter_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上报人姓名',
  `reporter_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上报人电话',
  `pet_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '宠物描述（如：种类，外貌，伤情）',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发现地点',
  `images` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '现场图片',
  `status` tinyint NULL DEFAULT 0 COMMENT ' 处理状态-（0-待处理，1-已审核(处理中)，2-已处理，3-已审核(未通过)）',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `handle_id` bigint NULL DEFAULT NULL COMMENT '处理人id',
  `handle_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '处理备注',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'admin' COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'admin' COMMENT '更新人',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除字段（0-未删除 1-已删除）',
  PRIMARY KEY (`rescue_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '救助登记表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_rescue
-- ----------------------------

-- ----------------------------
-- Table structure for tb_resource_category
-- ----------------------------
DROP TABLE IF EXISTS `tb_resource_category`;
CREATE TABLE `tb_resource_category`  (
  `category_id` bigint NOT NULL AUTO_INCREMENT,
  `category_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类名称',
  `order` tinyint NULL DEFAULT NULL COMMENT '排序',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态（0-正常，1-停用）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `create_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `shop_id` bigint NULL DEFAULT NULL COMMENT '店铺id',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`category_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商品种类表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_resource_category
-- ----------------------------

-- ----------------------------
-- Table structure for tb_shop
-- ----------------------------
DROP TABLE IF EXISTS `tb_shop`;
CREATE TABLE `tb_shop`  (
  `shop_id` bigint NOT NULL AUTO_INCREMENT COMMENT '店铺id',
  `shop_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '店铺名称',
  `user_id` bigint NULL DEFAULT NULL COMMENT '店主id',
  `legal_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '负责人手机号',
  `legal_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '负责人姓名',
  `legal_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '负责人身份证号',
  `license_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '营业执照号',
  `license_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '营业执照图片URL',
  `province` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '省份',
  `city` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '城市',
  `district` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '区县',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '详细地址',
  `owner_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系电话',
  `bussiness_hours` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '营业时间(如：09:00:00-18:00:00)',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '店铺描述，特色服务',
  `main_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '店铺主图',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态（0-正常营业，1-休息中，2-未审核）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `creare_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `review_id` bigint NULL DEFAULT NULL COMMENT '审核人id',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `review_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核意见',
  `is_deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除（0-未删除，1-已删除）',
  PRIMARY KEY (`shop_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '店铺，站点表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_shop
-- ----------------------------

-- ----------------------------
-- Table structure for tb_user_activity
-- ----------------------------
DROP TABLE IF EXISTS `tb_user_activity`;
CREATE TABLE `tb_user_activity`  (
  `ua_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `activity_id` bigint NULL DEFAULT NULL COMMENT '活动id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '报名用户',
  `contact_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系人姓名',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '联系人电话',
  `status` tinyint NULL DEFAULT NULL COMMENT '报名状态（0-已报名，1-报名取消，2-已签到，3-未签到）',
  `cancel_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `sign_time` datetime NULL DEFAULT NULL COMMENT '签到时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ua_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户报名表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_user_activity
-- ----------------------------

-- ----------------------------
-- Table structure for tb_user_notice
-- ----------------------------
DROP TABLE IF EXISTS `tb_user_notice`;
CREATE TABLE `tb_user_notice`  (
  `un_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `notice_id` bigint NULL DEFAULT NULL COMMENT '通知id',
  `user_id` bigint NULL DEFAULT 0 COMMENT '用户id',
  `read_status` tinyint NULL DEFAULT 0 COMMENT '阅读状态(0-未读，1-已读)',
  `read_time` datetime NULL DEFAULT NULL COMMENT '阅读时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`un_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '通知与用户之间的表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tb_user_notice
-- ----------------------------

-- ----------------------------
-- Table structure for tb_user_pet_collect
-- ----------------------------
DROP TABLE IF EXISTS `tb_user_pet_collect`;
CREATE TABLE `tb_user_pet_collect`  (
  `upc_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 ',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `pet_id` bigint NULL DEFAULT NULL COMMENT '收藏的宠物id',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`upc_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户收藏宠物领养表' ROW_FORMAT = DYNAMIC;

